UPDATE characters SET description = 'ベニマルはリムル=テンペストに名前をつけられた三番目の配下モンスター集団の一員である。元々はオーガだったが、配下であることに不安を感じており、それが一時的なものだと考えていた。しかし名前を受け取った後、彼は鬼人へと進化し、一時期はリムルの最も強力な部下となり、永遠に彼に仕えることを決意した。彼はジュラ・テンペスト連邦の首都であるリムル市に住んでいる。その後すぐに総司令官となり、テンペストの軍事力を直接指揮することになった。リムルが真の魔王へと昇格した際、ベニマルは公正な鬼へと進化し、', tags = ARRAY['赤髪','角','長身','筋肉質','真面目','ボーイッシュ','人外']::text[], voice_actor = '古川慎' WHERE character_id = 'CH012198'; -- ベニマル
UPDATE characters SET description = 'ヴェルドラ＝テンペストは、最強の竜である四大真竜の中で最年少である。彼はリムルとの契約によって結ばれており、かつて各地で暴れまわることで知られていた。リムルに名前をつけたのはヴェルドラであり、リムルから苗字を与えられたため、二人は同じ苗字を持つことになった。そのため、厳密に言えばリムルはヴェルドラの義兄弟と分類することができる。', tags = ARRAY['白髪','角','翼','長身','おじさん','クール','人外','魔王']::text[], voice_actor = '前野智昭' WHERE character_id = 'CH012200'; -- ヴェルドラ＝テンペスト
UPDATE characters SET description = 'ミリム・ナーヴァは、最古級で最強クラスの魔王の一人である。竜人族の身でありながら、「破壊者」というニックネームは伊達ではなく、決して相手にしてはいけない魔王として知られている。', tags = ARRAY['ピンク髪','ロングヘア','タレ目','角','翼','長身','お姉さん','魔王','人外','ドレス']::text[], voice_actor = '日高里菜' WHERE character_id = 'CH012201'; -- ミリム・ナーヴァ
UPDATE characters SET description = 'シオンは、リムルの最初の部下であり、専属秘書としてリムルの身の回りの世話を担当する「戦鬼」。よみがえりの指導者でもあり、リムルの最強戦力の一人であるとともに、彼女に会った多くの魔王たちから憧れの的とされている。', tags = ARRAY['白髪','ロングヘア','赤目','お姉さん','ニーソ','クール','ヒロイン','人外','魔王']::text[], voice_actor = '市道真央' WHERE character_id = 'CH012203'; -- シオン
UPDATE characters SET description = 'アメリカン・コロニーのメンバー。石化前の生活では、生涯一度も試合に負けたことのない全米女性格闘技チャンピオンとして君臨していた。その格闘技の実力を買われ、軍の特殊部隊からスカウトされた。', tags = ARRAY['筋肉質','褐色肌','格闘家','軍服']::text[], voice_actor = '東内マリ子' WHERE character_id = 'CH008108'; -- マヤ・ビッグス
UPDATE characters SET description = '上井陽は石化前の人間で元警察官で、司によって復活させられた。クロムの脱出後、責任を逃れるために死を装ったが、石の戦いの終結後、科学王国に加わることになる。罪滅ぼしとして、司に破壊された像をユズリハと共に修復する作業に当たっている。自分たちの世界の事情に疎いマグマと常に衝突している。', tags = ARRAY['黒髪','おじさん','真面目','社会人']::text[], voice_actor = '中島ヨシキ' WHERE character_id = 'CH008106'; -- 上井陽
UPDATE characters SET description = 'スイカは、石器時代の人間たちと一緒に村で暮らしている少女である。最大の特徴は頭に乗っている大きなスイカで、その中に入り込んで果物に変装することができる。千空がクロムと琥珀と一緒に近くの川で砂鉄を探していた時に、スイカと初めて出会う。スイカは以前誰の役にも立ったことがなかったため、千空が科学王国を築くのを手伝いたいという強い願いを持っている。彼女は科学王国の情報屋として働くようになり、時には「名探偵スイカ」と呼ばれることもある。', tags = ARRAY['ショートヘア','幼女','ロリ','小柄','元気','天然','小学生','探偵']::text[], voice_actor = '高橋花林' WHERE character_id = 'CH008105'; -- スイカ
UPDATE characters SET description = 'アメリカ領地の一員で、Dr.ゼノの整備士として働く現代人。Dr.ゼノの拉致後は、科学王国と手を組んでコーン・シティの建設に協力する。', tags = ARRAY['社会人']::text[], voice_actor = '安元洋貴' WHERE character_id = 'CH008104'; -- ブロディ・ダドリー
UPDATE characters SET description = '氷月は司城石化を解いて復活させた生き残り。司城に石化を解いてもらったため、当初はツカサ帝国のエリート構成員だった。氷月は何事にも楽観的な態度で接している。自分に不利な状況であっても冷静さを保ち続ける。若者だけを復活させ、誰もが奪い合わない共同体を作るというツカサの理念を共有していると主張しているが、氷月自身は社会進化論を信奉するエリート主義者である。彼は人類を啓蒙された者（もしくは強者）と啓蒙されない者（もしくは弱者）の二つのカテゴリーに分類する。彼は「', tags = ARRAY['クール','ナルシスト','ライバル','お姉さん']::text[], voice_actor = '石田彰' WHERE character_id = 'CH008103'; -- 氷月
UPDATE characters SET description = '小川杠は大樹の恋人であり、千空の友人です。小川杠は茶色い髪と茶色い瞳を持つ、すらりとした体格の若い女性です。彼女には目立つ石化の傷跡が2つあり、どちらも渦巻き状をしており、肩と首に位置しています。石化する前、小川杠は標準的な高校の制服を着ていました。石化から解放された後、彼女は両脇が開いた白い布製のワンピースと、それに合わせた布製の靴を着用しています。特徴的なのは、石化する前後を問わず、小川杠が白いヘアバンドを身に付けており、それはぼんやりとヘッドフォンのように頭を巻くような形をしていることです。', tags = ARRAY['茶髪','細身','高校生','ヒロイン','幼馴染','白肌']::text[], voice_actor = '市ノ瀬加那' WHERE character_id = 'CH008102'; -- 小川杠
UPDATE characters SET description = 'ルリはコハクの姉であり、コクヨの娘で、石神村の巫女を務めています。コハクに似た外見をしていますが、髪がより長く、より砂時計のような体型をしています。黒いサンドレスを着用し、首にロープを巻いています。', tags = ARRAY['黒髪','ロングヘア','お姉さん','巫女','グラマー']::text[], voice_actor = '上田麗奈' WHERE character_id = 'CH008119'; -- ルリ
UPDATE characters SET description = 'カセキは石神村の老練な職人である。千空が石神村にやって来た時、カセキは職人として紹介され、千空を通じて、自らの工芸への献身が十倍にも高まる。', tags = ARRAY['白髪','老人']::text[], voice_actor = '麦人' WHERE character_id = 'CH008109'; -- カセキ
UPDATE characters SET description = '石神百夜は、地球表面でペトリフィケーション（石化現象）が発生した時、国際宇宙ステーションに滞在していた日本人宇宙飛行士である。優しく茶目っ気があり、いかなる状況下においても、いつも何らかの方法で自分を楽しませ、物事を軽く考えようとするようなユーモア溢れた人物だった。', tags = ARRAY['白髪','おじさん','社会人','天然','マイペース']::text[], voice_actor = '三上哲' WHERE character_id = 'CH008120'; -- 石神百夜 
UPDATE characters SET description = '大木大樹は社交的で友好的、そして優しい性格の人物です。小さなことでも積極的に取り組み、勤勉な働き手です。自分にとって大切なものに関しては、非常に強い決意を持ちます。大きな声で話す傾向があり、役に立つことができれば、どんな仕事でも熱心に取り組みます。彼は粘り強く、決して諦めません。感情豊かで表現力が豊かである一方で、自分の感情をしっかりコントロールでき、決して冷静さを失わず、衝動的に行動することもありません。大木大樹は非常に頑健な肉体を持っており、友人の千空もこのことを認めています。彼はツカサの蹴撃に耐えることができた最初の人間です。', tags = ARRAY['黒髪','高校生','元気','真面目','幼馴染','筋肉質','長身']::text[], voice_actor = '古川慎' WHERE character_id = 'CH008101'; -- 大木大樹
