UPDATE characters SET description = '階級：五番隊隊長
斬魄刀：鏡花水月

藍染惣右介は丁寧で物静かな知識人で、部下に対しては名前で呼びかけることが多い。動揺や不安の素振りをほとんど見せず、あらかじめ状況全体を綿密に計画していることがほとんどである。何かに対峙した際、藍染は落ち着きを保ち無関心を装い、会話を引き出そうとして世間話をしかけることが多く、それが相手を怒らせることも少なくない。藍染は当初、非常に親切で尊敬される隊長として見られており、特に副隊長の雛森桃に慕われていた。しかし、実のところ彼はより深い一面を持っている——', tags = ARRAY['黒髪','ロングヘア','長身','クール','無口','ナルシスト','悪役','剣士','二重人格']::text[], voice_actor = '速水奨' WHERE character_id = 'CH007041'; -- 藍染惣右介
UPDATE characters SET description = '種族：死神
職位：六番隊副隊長
斬魄刀：蛇尾丸

阿散井恋次の性格は、他の死神と同様に多彩だ。生意気で風変わりな一面から、敗北後に落ち込むまで、さらには間抜けで笑える側面まで、様々な顔を見せる。シリーズの大部分では気楽で陽気なキャラクターとして描かれているが、自分や大切な者の生死がかかった状況では、極めて真摯になることができる。隊長である朽木白哉との関係は、かなり複雑なものとなっている。阿散井恋次は白哉を自分が乗り越えるべき目標として見ている。', tags = ARRAY['赤髪','元気','ボーイッシュ','ドジ','ツンデレ','ライバル','剣士']::text[], voice_actor = '伊藤健太郎' WHERE character_id = 'CH007030'; -- 阿散井恋次
UPDATE characters SET description = '# 涅マユリの説明

始解：�flemish足狡猾地蔵
卍解：金色足狡猾地蔵

涅マユリは護廷十三隊第12番隊の隊長であり、死神機関の第2代会長である。前任者で元隊長の浦原喜助が尸魂界に追放されたことで、その地位を手にした。彼の副隊長は自らが人工的に創造した「娘」である涅ネムである。', tags = ARRAY['白髪','メガネ','おじさん','クール','悪役','天才']::text[], voice_actor = '中尾隆聖' WHERE character_id = 'CH007040'; -- 涅マユリ
UPDATE characters SET description = '役職：第9戦隊副隊長
斬魄刀：風死綱（かぜしぬつな）
始解号令：刈り取れ、風死綱

修兵は極めて落ち着いた成熟した人物で、そのパンクめいた外見とは好対照をなしている。責任感が強く、基本的に暴力を避ける傾向にある。隊長の姿勢に似た誠実さを持つ男だったが、後になって隊長が裏切り者であることが明かされた。彼はよく恋次や吉良と一緒にいる姿が目撃されている。雛森を含む恋次と吉良は、護廷十三隊士官学校の時代から修兵を先輩として慕っていた。', tags = ARRAY['黒髪','ショートヘア','真面目','クール','先輩','剣士']::text[], voice_actor = '小西克幸' WHERE character_id = 'CH007026'; -- 檜佐木修兵
UPDATE characters SET description = 'コンは主にシリーズのコミカルな脇役として機能しており、一護の体に乗り移っていない通常のぬいぐるみ姿では、ほとんど尊重されず、軽蔑されています。彼が常に受ける滑稽で残酷な扱いが、ブリーチのコミカルな要素を提供しています。彼にある程度の敬意を払う数少ない人物の一人がチャドですが、チャドは大抵の場合彼を無視しています。彼のぬいぐるみ姿は、人気テレビ番組「肉食王国」の主人公「ポン吉」の類似品であり、これはチャドのお気に入りの番組です。この姿は空座町祭りの射的ゲームの景品でした。', tags = ARRAY['ショートヘア','小柄','ショタ','M属性','人外']::text[], voice_actor = '真殿光昭' WHERE character_id = 'CH007046'; -- コン
UPDATE characters SET description = '涅ネムは護廷十三隊第12分隊の副隊長で、隊長・涅マユリの部下である。涅ネムはマユリが人工肉体と人工魂魄の研究を組み合わせて造り上げた、人工的に創造された娘である。このような出自が彼女を内向的で憂鬱な性質へと駆り立てており、隊長の前では沈黙を保つことを好む。マユリとネムの関係は一般的な親子関係とはかけ離れており、マユリはネムの身の安全をあまり気にかけない傾向にある（戦闘時に彼女を囮として使うなど）。彼に有利なことといえば、時折ネムに対する懸念を示唆することがある程度である。', tags = ARRAY['銀髪','ロングヘア','タレ目','細身','白肌','無口','クール']::text[], voice_actor = '釘宮理恵' WHERE character_id = 'CH007042'; -- 涅ネム
UPDATE characters SET description = '所属：見滅帝国　職業：見滅帝国皇帝

滅却師の軍事組織である見滅帝国の現在の指導者。約1000年前に山本元柳斎に倒されることはなかったが、その時の詳しい状況は謎に包まれている。黒崎一護の不在に乗じて、ユーハバッハは精鋭部隊である星十字騎士団を率いてソウルソサエティに侵攻。彼らに死神全員の殲滅を命じた。侵攻が進む中、ユーハバッハは更木剣八と対峙し、両者の戦闘が始まる。ユーハバッハは剣八を圧倒的な力で打ち負かし、彼の弱さについてコメントする。', tags = ARRAY['白髪','長身','おじさん','軍服','クール','悪役']::text[], voice_actor = '菅生隆之' WHERE character_id = 'CH007039'; -- ユーハバッハ
UPDATE characters SET description = '綾瀬川弓親は一角舞三郎のナルシストな友人である。過去、二人は流魂街全域を共に巡り、戦いを求めていた。ある日、一角が更木剣八に敗れたことをきっかけに、剣八から「自分を倒せなかった者を殺すために生きよ」という講演を受ける。その後、剣八が隊長になったという知らせを聞いた二人は、彼の下で仕えるために十一番隊に入隊した。綾瀬川弓eternal は3番隊座を目指していた。理由は「三」という字が最も美しいと考えていたからだが、一角がその座を獲得したため、綾瀬川弓親は5番隊座に収まることにした。「5」という字が「3」に見えなくもないと考えたからである。', tags = ARRAY['ナルシスト','剣士','武道家']::text[], voice_actor = '福山潤' WHERE character_id = 'CH007051'; -- 綾瀬川弓親
UPDATE characters SET description = '職業：第1番隊副隊長

伊勢七緒は漫画・アニメ『BLEACH』に登場するキャラクターで、護廷十三隊第8番隊の副隊長。隊長である京楽春水の部下であり、死神女性協会の副会長を務めている。

七緒は非常に勉強熱心で、昼寝と酒をたしなむ隊長の書類仕事やつまらない雑務のほとんどを引き受けている。二人の関係は、色々なことを考えると非常に良好だ。彼女の斬魄刀がどの程度まで進化しているかは未だ不明だが、七緒自身は剣術があまり得意ではないと認めている。しかし、彼女は～', tags = ARRAY['黒髪','ロングヘア','お姉さん','真面目','剣士']::text[], voice_actor = '生天目仁美' WHERE character_id = 'CH007032'; -- 伊勢七緒
UPDATE characters SET description = '矢胴丸リサは、京楽春水隊長の配下で8番隊の元副隊長である。眼鏡をかけた長身で、濃い色の髪を三つ編みにしたキャラクターで、空座高校の生徒たちが着用するより西洋的なスタイルの制服ではなく、セーラー服を着ている。現在の外見と一貫性を保つため、彼女がゴテイ13に所属していた当時の死神の制服は、スカートのような短めの袴だった。気が短く見えるし、エロ漫画（特に女性向け漫画）を読むことが好きなようである。また非常に好奇心が強く、当時、隊長会議を盗み聞きするほどの積極性がある。', tags = ARRAY['黒髪','三つ編み','メガネ','長身','制服','先輩']::text[], voice_actor = 'さより 石塚' WHERE character_id = 'CH007045'; -- 矢胴丸リサ
