UPDATE characters SET description = '陽務楽郎は「サンラク」というニックネームで知られており、クソゲーの愛好家である。クソゲーとはバグが多く、不公正なゲームバランス、そして劣悪なAIで知られるゲームのことだ。彼は友人たちの間では、クソゲー狂の変わり者として有名だ。クソゲーをプレイして磨き上げた経験のおかげで、サンラクはゲームから不利な条件を突きつけられるほど、より一層やる気を高め、優れたプレイヤーへと成長していく。', tags = ARRAY['主人公','天才','マイペース']::text[], voice_actor = '内田雄馬' WHERE character_id = 'CH007052'; -- 陽務楽郎
UPDATE characters SET description = 'シャングリラ・フロンティアの超一流プレイヤーで、ゲーム内で最高の瞬間火力を叩き出したプレイヤーに与えられる特別な称号「アタックホルダー」の持ち主。ゲーム内では伝説級の装甲に身を包んだ筋骨隆々の男性キャラとして現れるが、現実では魅力的な少女であり、サンラクに秘かな想いを寄せている。', tags = ARRAY['ツインテール','ツンデレ','ヒロイン','ボーイッシュ']::text[], voice_actor = '和氣あず未' WHERE character_id = 'CH007054'; -- 斎賀玲
UPDATE characters SET description = 'エムルの父親にして、ヴォーパルバニーの種族の族長。他のヴォーパルバニーとは比べ物にならないほど巨大で圧倒的な肉体を持ち、その姿を目にするだけで周囲を圧倒する威厳に満ちている。エムルの案内でウサギ王国ラビツァを訪れたスンラクの強さと大胆さに感銘を受け、彼に様々な試練を与える。', tags = ARRAY['白髪','うさ耳','しっぽ','長身','筋肉質','おじさん','父親']::text[], voice_actor = '大塚明夫' WHERE character_id = 'CH007053'; -- ヴァイスアッシュ
UPDATE characters SET description = '天音久遠は、オルセロットの名でも知られており、アーサー・ペンシルゴンの弟である。', tags = NULL, voice_actor = '山下誠一郎' WHERE character_id = 'CH007081'; -- 天音久遠
UPDATE characters SET description = 'エムルの姉。ウサギの館内にあるスキル育成専門施設「スキルガーデナー」でスキルを販売している。いつも穏やかな笑顔を浮かべており、のんびりとした口調が特徴。スキルの組み合わせにも長けている。商売っ気があり、あらゆる機会を見つけては他者に自分の商品を買わせようと勧めてくる。', tags = ARRAY['おっとり']::text[], voice_actor = '安野希世乃' WHERE character_id = 'CH007082'; -- エルク
UPDATE characters SET description = 'シャングリラ・フロンティアの強大なユニークモンスター「墓守のウェザエモン」の秘密を握る、特別なNPC。隠れた庭園に生息し、その場所は彼岸花が咲き乱れる秘密エリアとなっている。', tags = ARRAY['人外']::text[], voice_actor = '瀬戸麻沙美' WHERE character_id = 'CH007075'; -- セツナ
UPDATE characters SET description = '分析クラン「ライブラリー」のリーダー。シャングリラ・フロンティアの謎を解き明かすという究極の目標を掲げており、ユニークモンスター撃破後のスンラクに接触する。愛らしい魔法少女のような見た目に似合わず、意外と低くて渋い声が特徴。', tags = ARRAY['クール','社会人','魔法使い']::text[], voice_actor = '中田譲治' WHERE character_id = 'CH007084'; -- キョージュ
UPDATE characters SET description = '修羅会の副長で、プレイヤーキルを主な活動とする過激派PKクラン。戦略と情報戦に長けており、「巨人狩り」の異名を持つ。これは自分より遥かに高レベルなプレイヤーをも倒す能力から得た称号である。かつて別のゲームでサンラクとオイカッツォと対戦した過去があり、現在は宿敵にして同志というゲーム仲間の関係にある。現在、あるユニークモンスターの討伐を目指している。', tags = ARRAY['お姉さん','社会人','クール','ライバル','S属性']::text[], voice_actor = '日笠陽子' WHERE character_id = 'CH007068'; -- 天音永遠
