UPDATE characters SET description = '異国の呼吸法「気」を用いて超人的な力を引き出す格闘家。修行一筋の人生を送った後、運命の美男子との出会いを求めて道場を飛び出し、冒険者になった。しかし仲間に恵まれず、一人旅の最中にロイドと出会う。美しい顔立ちに弱く、明るく興奮しやすい性格。', tags = ARRAY['お姉さん','元気','天然','格闘家','武道家','筋肉質','マイペース']::text[], voice_actor = '関根明良' WHERE character_id = 'CH005040'; -- タオ
UPDATE characters SET description = 'ウェブ・ブライテッドで、体を覆う魔力を粘り着いた液体に変換する能力を持つ。ジェイドが個人的な事情で故郷に戻った後、ガリレアは暗殺者ギルドの指揮を任されることになる。自身の蜘蛛の糸と強靭な体躯を組み合わせた戦闘スタイルを駆使して戦う。仲間たちの個性をよく理解しており、混乱した戦闘の最中でも的確な指揮を発揮する。', tags = ARRAY['男の娘','魔法使い','クール','真面目','筋肉質','忍者']::text[], voice_actor = '杉田智和' WHERE character_id = 'CH005039'; -- ガリレア
UPDATE characters SET description = 'サルーム王国の第二王子で、ロイドの兄である。文武両道に優れた現在の王位継承者。宮廷では常に注目の的となっているが、傲慢さに欠けており、部下に対して思慮深く接することで、多くの勢力の支持を得ている。アルベルト=ディ=サルームはロイドの魔術の才能を他者が見落とす中で認め、将来的に価値のある同盟者となる可能性を秘めた人物として考えている。', tags = ARRAY['真面目','クール','天才']::text[], voice_actor = '堀江瞬' WHERE character_id = 'CH005037'; -- アルベルト=ディ=サルーム
UPDATE characters SET description = '暗殺者ギルドの一員で、全員が懸賞金をかけられている。このギルドのメンバーは皆、「呪われし者」と呼ばれるマナに異常をきたす先天的な条件を持っており、レンの場合は皮膚から毒を分泌することができ、「毒蛾のレン」という異名を得ている。普段は厚手の衣装を着用しており、肌が露出すると周囲に毒を撒き散らすことが可能。少々のボーイッシュな性格だが、自分の力ゆえに内気な一面を持つ。', tags = ARRAY['黒髪','ボーイッシュ','人外']::text[], voice_actor = '高橋李依' WHERE character_id = 'CH005038'; -- レン
UPDATE characters SET description = 'ワープの呪いを受けた者であり、異常なほどに柔軟な関節を持つため、ネズミのようにどんな狭い隙間にも入り込むことができることから「巨大ネズミのバビロン」という名で知られている。身体の柔軟性を活かした格闘術の使い手であり、感情を隠す細い目が特徴的。戦闘中は敵を挑発するような独特の笑い方をする。ギルドの他のメンバー同様、一見すると無関心に見えるが、仲間を非常に大切にしており、冷静さを保ち信頼できる判断力を備えていることで知られている。', tags = ARRAY['ジト目','格闘家','クール','マイペース']::text[], voice_actor = '土岐隼一' WHERE character_id = 'CH005043'; -- バビロン
UPDATE characters SET description = 'サルーム王国の第四王子であり、ロイドの兄の一人。幼い頃から魔術に惹かれていたが、才能に恵まれなかったため、10歳の時に鍛冶職人の道を志し、その修行のために隣国バートラムへ渡った。魔力を宿した剣を製造することが夢であり、サルーム王国に魔剣士団を設立することを目指している。職人気質の厳しい一面を持ちながらも、心優しき人物。', tags = ARRAY['魔法使い','真面目']::text[], voice_actor = '広瀬裕也' WHERE character_id = 'CH005046'; -- ディアン=ディ=サルーム
UPDATE characters SET description = '古い魔法を使う悪魔で、かつてサロウム王国を崩壊寸前にまで追い詰めた存在。王国の秘密の書庫に鍵をかけて封印された禁書の中に数世紀間閉じ込められていたが、ロイドによって解放される。初めての出会いで、ロイドの計り知れないほどの魔力と魔術に圧倒され、彼に降伏する。その後、可愛らしい使い魔の姿へと変わり、ロイドに仕える。', tags = ARRAY['悪役','魔法使い','人外','小柄']::text[], voice_actor = 'ファイルーズあい' WHERE character_id = 'CH005035'; -- グリモワール
UPDATE characters SET description = 'ロイドに仕える忠実なメイド。サルーム王国に仕え、ロイドの教育と保護を担当している。冒険者たちから羨まれるほどの剣の腕前を持ち、「銀刃の姫君」の異名で知られている。一見するととても優しく見えるが、剣の修行となると厳しい一面を見せる。過去には冷徹な剣士であり、戦闘中はその本来の姿が表れることがある。', tags = ARRAY['銀髪','ロングヘア','お姉さん','メイド服','クール','ヤンデレ','ヒロイン','騎士','剣士','二重人格']::text[], voice_actor = 'Lynn' WHERE character_id = 'CH005042'; -- シルファ
UPDATE characters SET description = '呪われた者たちのグループを集めて暗殺者ギルドを創設し、その指導者として活動している。「幻影の呪われた者」として知られ、自らの意思とは関係なくランダムな場所にテレポートする力を持つ。元々はロードスト領を統治する名門貴族の三男だった。その領土を政治力で支配する親族に対抗するために、呪われた者たちのチームを組織した。心優しく思いやりのある人物で、暗殺者ギルドのメンバーたちは彼の指導を頼りにしていたが、やがて～', tags = ARRAY['黒髪','男の娘','クール','悪役','魔法使い','異世界転生']::text[], voice_actor = '島﨑信長' WHERE character_id = 'CH005044'; -- ジェイド
UPDATE characters SET description = '「痛みの祝福者」の異名を持つタリアは、視界に入った者とリンクする能力を持つ。リンク後は彼女と相手が受けたあらゆるダメージを共有することになる。この能力の性質上、タリアは戦闘において自らにダメージを与えることを戦術として用いるため、「百の痛みのタリア」と呼ばれている。友人のためなら進んで苦痛に耐える自己犠牲的な性格の持ち主であり、ゴシップが大好きで、ギルドの唯一の女性メンバーとしてレンの面倒をよく見ている。', tags = ARRAY['M属性','魔法使い','超能力']::text[], voice_actor = '明坂聡美' WHERE character_id = 'CH005041'; -- タリア
UPDATE characters SET description = '桔梗セリは吸血鬼であり、人生を楽しむことを求めているギャルだが、次第に楽しさを見出すことが難しくなっていく。', tags = ARRAY['吸血鬼','元気']::text[], voice_actor = '戸松遥' WHERE character_id = 'CH009849'; -- 桔梗セリ
UPDATE characters SET description = '彼女は吸血鬼であり、平田ニコのグループに属する友人である。', tags = ARRAY['吸血鬼','人外']::text[], voice_actor = '伊藤静' WHERE character_id = 'CH009856'; -- 本田カブラ
UPDATE characters SET description = '小繁縷ミドリはヴァンパイアであり、メイド喫茶「ヴァンプス」ナンバーワンメイドである。', tags = ARRAY['吸血鬼','メイド服']::text[], voice_actor = '大空直美' WHERE character_id = 'CH009858'; -- 小繁縷ミドリ
UPDATE characters SET description = 'つまらない日常に次第に落ち着きを失っていく中学2年生の少年。自分を奮い立たせるため、夜間に外出して町をさまよう。吸血鬼になることを望んでいる。', tags = ARRAY['黒髪','ショタ','中学生','中二病']::text[], voice_actor = '佐藤元' WHERE character_id = 'CH009846'; -- 夜守コウ
UPDATE characters SET description = '平田ニコは吸血鬼であり、夜間授業を担当する教師である。', tags = ARRAY['吸血鬼','教師']::text[], voice_actor = '喜多村英梨' WHERE character_id = 'CH009848'; -- 平田ニコ
UPDATE characters SET description = '変わり者の私立探偵。事件を解決していない時は、煙草を吸うのが好き。', tags = ARRAY['お姉さん','クール','探偵','マイペース']::text[], voice_actor = '沢城みゆき' WHERE character_id = 'CH009847'; -- 鶯餡子
UPDATE characters SET description = '朝井アキラは、関孝と関真昼の幼馴染で、孝と同じアパートに住んでいる。アキラは学校の義務に忠実に従う真面目な生徒である。孝と真昼とは仲が良く、親密な関係を保っている。吸血鬼に対する疑いの心が強く、彼らとあまり関わりたくないと考えている。孝に強く執着しているようで、しばしば彼に引っ張られてトラブルに巻き込まれている。', tags = ARRAY['黒髪','真面目','幼馴染','中学生']::text[], voice_actor = '花守ゆみり' WHERE character_id = 'CH009854'; -- 朝井アキラ
UPDATE characters SET description = '蘿蔔ハツカは小柄な体格をした両性具有的な体型の男性で、上半身は男性的でありながらも非常に細く、腰部は女性的な特徴を持っている。肩まで届く黒髪と細長い顔立ちが特徴だ。彼は女性的なファッションを好んでおり、本人曰くそれが自分に似合うからだという。普段着ているのはドレスとコートが主で、足元は濃色のカーフ丈ブーツを履いており、家の中では小ぶりな靴やスリッパを履いている。', tags = ARRAY['黒髪','ロングヘア','小柄','細身','ドレス','男の娘']::text[], voice_actor = '和氣あず未' WHERE character_id = 'CH009852'; -- 蘿蔔ハツカ
