UPDATE characters SET description = 'フェンリースは、魔王軍の四天王の一人だったガロ族の戦士フェンガリルの妹。フリオと出会い、彼とのまったりとした結婚生活を始める。ガロ族の血を引く彼女は喧嘩っ早い一面があるが、何より大切なのはフリオへの想い。彼を心から愛している。', tags = ARRAY['ツンデレ','ヒロイン','人外']::text[], voice_actor = '釘宮理恵' WHERE character_id = 'CH005070'; -- フェンリース
UPDATE characters SET description = '平和を愛する心優しき青年。突然、異世界へ「勇者候補」として召喚される。レベル1では凡庸な能力しかなく、不適格として追放されるが、レベル2に到達した瞬間、彼のステータスは「∞」に変わる。常人では扱いようのない力を手に入れるのだ。', tags = ARRAY['青髪','勇者','異世界転生']::text[], voice_actor = '日野聡' WHERE character_id = 'CH005071'; -- フリオ
