UPDATE characters SET description = 'Momota''s entourage.  The names of Momota and his gang are in reference to the Japanese folklore of Momotarou. His name is a common Japanese family name and does not reference the third member of Momotarou''s entourage, the pheasant (キジ, kiji), as pointed out by Morihito.', tags = ARRAY['男の娘']::text[], voice_actor = '櫻井トオル' WHERE character_id = 'CH008974'; -- 山本
