UPDATE characters SET description = '真嘉二中学校の生徒会長。『ジキル博士とハイド氏』のジキルの末裔であり、自分では制御できない破壊衝動を秘めている。', tags = ARRAY['黒髪','中学生','生徒会長','真面目','二重人格']::text[], voice_actor = '阿座上洋平' WHERE character_id = 'CH008968'; -- 藤木累
