UPDATE characters SET description = '朝野高校の生徒会広報担当。ワイルドな外見に反して落ち着いた性格で、普段はしっかり仕事をこなしているが、物を壊すことを楽しむときは野性的な一面を見せることもある。', tags = ARRAY['高校生','クール','真面目','生徒会長','筋肉質']::text[], voice_actor = '三宅健太' WHERE character_id = 'CH008941'; -- バースト
