UPDATE characters SET description = '前の世界では、戦闘力と権力の両面で自分の国の頂点に立つ者として生きていたが、ある日暗殺された。しかし、キング・グレイとして死を迎えたはずなのに、アーサー・レイウィンとして目覚めてしまう。レイウィン家に転生した後、グレイは前の人生とは違い、この人生を全力で生きることを決意する。愛される者として、そして前の人生では得られなかった友人と家族に囲まれて生きるために。', tags = ARRAY['主人公','異世界転生']::text[], voice_actor = '藤原夏海' WHERE character_id = 'CH009007'; -- アーサー・レイウィン
UPDATE characters SET description = 'ジャスミン・フレームスワースは冒険者パーティ「ツインホーンズ」のメンバーで、アーサーの両親の元仲間である。無口で対人関係に苦手意識を持つ一面がありながらも、双剣を操る優秀なオーグメンター（強化魔法使い）であり、鋭い観察眼と優れた学習能力で知られている。', tags = ARRAY['無口','クール','魔法使い','剣士','天才']::text[], voice_actor = '小見川千明' WHERE character_id = 'CH009011'; -- ジャスミン・フレームスワース
UPDATE characters SET description = NULL, tags = NULL, voice_actor = '高橋伸也' WHERE character_id = 'CH009008'; -- ダーデン・ウォーカー
UPDATE characters SET description = 'テシア・エラリスは森で奴隷商人に捕らえられたエルフの少女で、後にアーサーと運命的に出会う。厳しい環境で育ったため気心が知れるまでは警戒心が強く無愛想だったが、アーサーとの出会いを機に次第に明るさを取り戻し、笑顔が増えていく。', tags = ARRAY['エルフ','ロリ','ツンデレ','ヒロイン']::text[], voice_actor = '市ノ瀬加那' WHERE character_id = 'CH009009'; -- テシア・エラリス
