UPDATE characters SET description = '七倉凛は『疑似ハーレム』の主人公。光坂高校の演劇部に所属しており、優れた演技力を活かして演劇部の仲間・北浜英二に対して様々なキャラを演じ分けることで、彼を落とそうと目論んでいる。親しみやすい性格だが、片思いの相手に対しては奥手な一面があり、そのため彼を楽しませるために疑似的な人格を演じている。人を笑わせることが得意で、自分も笑うことが好き。七倉凛は実力派の女優で、英二のために調子っぱずれなキャラから、ツンデレ、クール系、かわいらしいキャラまで、様々なタイプの少女像を演じ分けることができる。また、彼女は', tags = ARRAY['黒髪','高校生','主人公','ツンデレ','クール','元気','二重人格']::text[], voice_actor = '早見沙織' WHERE character_id = 'CH006214'; -- 七倉凛
UPDATE characters SET description = '北浜英二は七倉凛の恋愛対象である。光坂高校に通う彼は演劇部でりんと出会う。りんは彼のハーレムを作るという願いを叶えることにする。', tags = ARRAY['黒髪','高校生']::text[], voice_actor = '岡本信彦' WHERE character_id = 'CH006213'; -- 北浜英二
