UPDATE characters SET description = 'モニカの使い魔。黒い猫の姿をしているが、人間の言葉を理解して話すことができる。モニカが落ち込んでいるときは、肉球を触らせて彼女を癒してあげる。モニカ以外の人間の名前を覚えるのが苦手。ただし、人間が書いた小説を読むのが好きで、小説家ダスティン・ガンサーの大ファンである。', tags = ARRAY['黒髪','猫耳','しっぽ','人外','無口']::text[], voice_actor = '生天目仁美' WHERE character_id = 'CH009867'; -- ネロ
UPDATE characters SET description = '結界魔法使いと契約した上位の風精霊。愛称は「リン」。普段はメイド姿で現れるが、他の姿にもなることができる。モニカとルイスの連絡役として活動し、モニカの極秘任務をサポートしている。人間らしく振る舞うことをまだ学習中のようだ。', tags = ARRAY['メイド服','魔法使い','人外']::text[], voice_actor = '市道真央' WHERE character_id = 'CH009868'; -- リィンズベルフィード
UPDATE characters SET description = 'メアリー・ハーヴェイは七賢人の一人である星読みの魔女であり、リディル王国随一の占星術師にして預言者である。', tags = ARRAY['魔法使い']::text[], voice_actor = '能登麻美子' WHERE character_id = 'CH009863'; -- メアリー・ハーヴェイ
UPDATE characters SET description = 'セレンディア学園の生徒会書記。シェイルベリー侯爵の娘。成績優秀で語学も堪能。その立ち振る舞いと行動は常に完璧だと言われており、学園の三大美女の一人に数えられている。フェリックスとは幼い頃からの友人で、周囲からはフェリックスの婚約者として最適の人物だと見なされている。', tags = ARRAY['金髪','ロングヘア','高校生','制服','真面目','お嬢様','幼馴染']::text[], voice_actor = '日笠陽子' WHERE character_id = 'CH009865'; -- ブリジット・グレイアム
UPDATE characters SET description = 'ニール・クレイ・メイウッドはセレンディア学園の生徒会で総務を担当している。男爵メイウッドの息子で、様々な案件の仲介・交渉を行う「調停者の家門」に属している。モニカと同じ高校の2年生。優しく親切で真摯な性格だが、影響を受けやすい一面もある。一方で、舞台裏では積極的に活動する縁の下の力持ち的存在である。', tags = ARRAY['高校生','真面目']::text[], voice_actor = '榊原優希' WHERE character_id = 'CH009861'; -- ニール・クレイ・ メイウッド
UPDATE characters SET description = 'ミネルヴァ魔法訓練学園でモニカの昔の友人。', tags = ARRAY['魔法使い','高校生']::text[], voice_actor = '渡辺明乃' WHERE character_id = 'CH009866'; -- バーニー・ジョーンズ
