UPDATE characters SET description = 'セレンディア学園の元生徒会会計。生徒会の資金を横領していたところを見つかり、学園から退学処分を受けた。', tags = ARRAY['悪役','社会人']::text[], voice_actor = '市川蒼' WHERE character_id = 'CH009862'; -- アーロン・オブライエン
UPDATE characters SET description = 'ルイス・ミラーは七賢者の一人で、結界魔法の使い手である。モニカと同時に七賢者に選ばれたため、彼女のことを「同僚」と呼んでいる。第一王子派閥に属しながらも、陛下から第二王子の護衛を務めるよう極秘命令を受け、その任務をモニカに押し付けた。最愛の妻ロザリーには逆らえないようである。', tags = ARRAY['黒髪','おじさん','魔法使い','クール','社会人']::text[], voice_actor = '諏訪部順一' WHERE character_id = 'CH009864'; -- ルイス・ミラー
UPDATE characters SET description = 'モニカの小屋の近くの村に住む、気の強い少女。いつもモニカのところへ物を届けるのは彼女の役目だ。', tags = ARRAY['元気','ボーイッシュ','小柄']::text[], voice_actor = '土屋李央' WHERE character_id = 'CH009872'; -- アニー
