UPDATE characters SET description = '街出身の男の子で、結構ドジなところがある。思わず本音を口に出してしまうことがある。とても寒がりで、冷気に弱い。', tags = ARRAY['黒髪','長身','ショタ','ドジ']::text[] WHERE character_id = 'CH003959'; -- 四季翼
UPDATE characters SET description = 'つばさ識の一学年上の先輩。冬月と同じギャルで、冬月から非常に慕われている。勉強の才能は特に優れていると評価されているが、性格は本当に気が弱く、自信がない。', tags = ARRAY['黒髪','高校生','小柄','先輩','天才','ハジデレ']::text[] WHERE character_id = 'CH003958'; -- 夏川怜奈
UPDATE characters SET description = 'つばさとみなみの同級生。黒髪で物静かな性格、北海道方言を使わないというみなみとは正反対の女の子。ゲーム好きの一面がありながらも、ファッション誌やメイク誌を読んで身だしなみに気を配り、周囲に溶け込もうとしている。大量の汗をかきやすい体質のため、運動全般を避けており、やがて人間関係そのものから遠ざかっていった。友人がいない状況の中で、つばさに親近感を覚えた秋野沙友理は、彼とみなみの友達になる。', tags = ARRAY['黒髪','細身','無口','クール']::text[] WHERE character_id = 'CH003957'; -- 秋野沙友理
UPDATE characters SET description = '北見北陵高校でツバサの同級生の16歳の女の子。人気者で社交的。ギャル文化を実践しており、髪を金髪に染めたり冬でも短いスカートを履いたり、冬でも手袋をつけずにスマートフォンを使える状態にしている。ツバサに好意を寄せているようで、彼を困らせたり動揺させたりするために積極的にからかうのを楽しんでいる。', tags = ARRAY['金髪','高校生','ミニスカ','小悪魔','元気','S属性','ツンデレ']::text[] WHERE character_id = 'CH003956'; -- 冬木美波
UPDATE characters SET description = NULL, tags = NULL WHERE character_id = 'CH003967'; -- 冬木桃子
