UPDATE characters SET description = NULL, tags = NULL WHERE character_id = 'CH003961'; -- 戸口美彩
UPDATE characters SET description = 'アスカの友人でクラスメートで、自分をミナミの一番のファンだと称している。長髪で大きなメガネをかけている。ミナミと同じ中学校に進学したことで、好きなキャラクターに似ているということからミナミに夢中になっている。日菜はミナミをネットでフォローしており、ツバサを含むミナミの周囲のあらゆることを徹底的にリサーチしている。', tags = ARRAY['ロングヘア','メガネ','中学生','天然']::text[] WHERE character_id = 'CH003965'; -- 日菜
UPDATE characters SET description = '冒険者志望だったノールだが、12歳の時に「何もかもが才能ゼロ」と烙印を押されてしまう。しかし夢を諦めず、山に籠もって「パリイ」の技を磨き続けた結果、千の刃を弾き飛ばせるまでに成長した。現在はギルドに最下級ランクで登録されており、町での雑用をこなしながら日々を過ごしている。', tags = ARRAY['ショタ','主人公','剣士','真面目','元気']::text[], voice_actor = '濱野大輝' WHERE character_id = 'CH006220'; -- ノール
UPDATE characters SET description = 'クレイ王国の第一王女で、正式名はリネバーグ・クレイ。王都訓練学園を全科目で史上最高点という成績で卒業し、あらゆる能力に秀でている。六つの属性系統全てのスキルを網羅的に習得している。かつてモンスターに襲われた際にノールに救われたことで、それ以来彼を慕うようになり、親しみを込めて「先生」と呼んでいる。', tags = ARRAY['天才','魔法使い','お嬢様']::text[], voice_actor = '前川涼子' WHERE character_id = 'CH006221'; -- リーン
UPDATE characters SET description = 'クレイ王国の騎士であり、戦士団の副団長。「神盾」と呼ばれる特殊な防御能力を持ち、リンネの護衛として活躍している。元は孤児だったが、「盾聖」ダンダルグに拾われ、自らの力の使い方を教わった。', tags = ARRAY['騎士']::text[], voice_actor = '森なな子' WHERE character_id = 'CH006229'; -- イネス・ハーネス
UPDATE characters SET description = '怪物たちと自由に意思疎通できる特殊能力を持つ心優しい少年。遠い昔に絶滅したとされている魔族の末裔であり、邪悪な存在として扱われてきた。奴隷商人のもとで非常に不幸な幼少期を過ごしている。', tags = ARRAY['ショタ','おっとり','人外']::text[], voice_actor = '村瀬歩' WHERE character_id = 'CH006228'; -- ロロ
UPDATE characters SET description = 'クレイ王国を守護する六大君主の一人。レンジャーの最高位である「弓聖」の称号を授かっており、王都のレンジャー養成学校の講師も務めている。', tags = ARRAY['教師','クール']::text[], voice_actor = '豊口めぐみ' WHERE character_id = 'CH006226'; -- ミアンヌ
UPDATE characters SET description = 'クレイ王国の国王であり、世界最古の迷宮「帰らずの迷宮」を擁する国の統治者。リンネとレインの父親でもある。冒険者時代は六大主権者と共に「失われし迷宮」を探索し、その最奥部で黒刃を発見した。現在は冒険から身を引いているものの、王国における最高戦力の一つであることに変わりなく、国を覆う不吉な気配を感じ取り、常に警戒態勢を整えている。', tags = ARRAY['おじさん','父親','剣士']::text[], voice_actor = '山野井仁' WHERE character_id = 'CH006224'; -- クレイス王
UPDATE characters SET description = 'クレイス王国を守護する六大主権者の一人。聖職者の最高位である「癒しの聖人」の称号を与えられており、王都の聖職者学園の教官としても活動している。', tags = ARRAY['教師','シスター','真面目','クール']::text[], voice_actor = '羽多野渉' WHERE character_id = 'CH006232'; -- セイン
UPDATE characters SET description = 'クレイス王国の第一王子で、その本名はレイン・クレイスである。落ち着きと冷静さを兼ね備えた性格で、クレイス王の側近としても仕えている。', tags = ARRAY['クール','真面目']::text[], voice_actor = '寺島惇太' WHERE character_id = 'CH006223'; -- レイン・クレイス
UPDATE characters SET description = 'クレイズ王国を守護する六大主権者の一人。盗賊の最高位である「隠聖」の称号を持ち、王都の盗賊学校の講師も務めている。', tags = ARRAY['おじさん','教師','忍者']::text[], voice_actor = '関俊彦' WHERE character_id = 'CH006222'; -- カルー
