UPDATE characters SET description = '王国ボエラテのために、ハイデンの遺跡からアルカナサイトを奪おうとする対立勢力の将軍。黒竜の紋章を持つ。', tags = ARRAY['黒髪','長身','おじさん','軍服','クール','悪役']::text[], voice_actor = '安元洋貴' WHERE character_id = 'CH009941'; -- ドレル
UPDATE characters SET description = 'クレバテス-魔獣の王を倒すために立ち上がった13人の勇者の一人。ハイデン王から神聖な宝「岩燕」を授けられた。かつて「剣聖」の称号を得た勇者マルゴの娘である。', tags = ARRAY['勇者','剣士']::text[], voice_actor = '白石晴香' WHERE character_id = 'CH009921'; -- アリシア
