UPDATE characters SET description = '織田晶は普通の高校生だ。病弱な母と妹と一緒に暮らしている。学校が終わるたびに、家計を助けるためにアルバイトで雑用をこなしている。ある日、モリガンという世界のレティス王国の王が、織田晶とクラスメイトたちを王国に召喚し、魔王を倒して王国を脅威から守らせることになる。', tags = ARRAY['黒髪','高校生','主人公','社会人','異世界転生']::text[], voice_actor = '大塚剛央' WHERE character_id = 'CH010731'; -- 織田晶
