UPDATE characters SET description = '咲の実母であり、悠太の義母。前夫との離婚後、咲を一人で育て上げるために懸命に働き続け、その後再婚した。', tags = ARRAY['母親','お姉さん','社会人']::text[], voice_actor = '上田麗奈' WHERE character_id = 'CH006286'; -- 綾瀬亜季子
UPDATE characters SET description = 'ユウタの実の父親であり、サキの義父。様々な事情から前妻と離婚した後、綾瀬秋子と再婚した。ユウタとサキとは良好な関係を築いている。', tags = ARRAY['黒髪','おじさん','父親','社会人']::text[], voice_actor = '小林親弘' WHERE character_id = 'CH006285'; -- 浅村太一
UPDATE characters SET description = '勇太の義妹で、高校2年生。両親の再婚により勇太の義妹となった。派手な服装のため、不良生徒と見なされており、クラスではあまり好かれていない。', tags = ARRAY['高校生','ヒロイン','ボーイッシュ']::text[], voice_actor = '中島由貴' WHERE character_id = 'CH006277'; -- 綾瀬沙季
UPDATE characters SET description = 'ユウタのクラスメイト。学校ではユウタほぼ唯一の友人。野球部に所属しており、オタク気質を持つ。', tags = ARRAY['黒髪','高校生','クール']::text[], voice_actor = '濱野大輝' WHERE character_id = 'CH006283'; -- 丸友和
UPDATE characters SET description = '咲の義兄で、高校2年生。両親の再婚により咲の義兄となった。ごく普通の高校生だが、どこか他人との距離を置いている。本が好きなことでも知られており、まさに活字中毒といえるほどである。', tags = ARRAY['黒髪','高校生','主人公','クール','真面目']::text[], voice_actor = '天崎滉平' WHERE character_id = 'CH006278'; -- 浅村悠太
UPDATE characters SET description = '咲の同級生。いつも元気で、お節介なところがある。咲が孤立しているのを見かねた奈良坂真綾は、つい首を突っ込んでしまい、二人は友人になっていく。', tags = ARRAY['黒髪','元気','高校生']::text[], voice_actor = '鈴木愛唯' WHERE character_id = 'CH006281'; -- 奈良坂真綾
