UPDATE characters SET description = NULL, tags = ARRAY['男の娘']::text[], voice_actor = '新井良平' WHERE character_id = 'CH006282'; -- 新庄圭介
UPDATE characters SET description = 'アメリア・レヴィットは魔術師の家系に生まれたが、魔術の素質を持たなかった。魔術の存在を知らされないまま育てられた彼女の代わりに、妹のヴェラ・レヴィットが家の知識を受け継ぐことになった。医学の道を進んだアメリア・レヴィットは、やがてスノーフィールド中央病院の医師となった。ユウカクと黒岡夫人の実験的魔術により、娘の黒岡椿が昏睡状態に陥ったあと、アメリア・レヴィットは彼女の主治医となった。', tags = ARRAY['社会人']::text[], voice_actor = '北原沙弥香' WHERE character_id = 'CH011500'; -- アメリア・レヴィット
UPDATE characters SET description = NULL, tags = ARRAY['茶髪','ロングヘア','おじさん','社会人','ナルシスト']::text[], voice_actor = '森久保祥太郎' WHERE character_id = 'CH011502'; -- アレクサンドル・デュマ
UPDATE characters SET description = 'ティーネ・チェルクはスノーフィールドで行われた偽りの聖杯戦争におけるアーチャーのマスターである。ティーネの民族は、かつてスノーフィールド地域を千年にわたって守ってきた先住民だったが、二十世紀初頭に政府と偽りの聖杯戦争の準備のために土地を確保しようとした魔術師集団によって追い出されてしまった。ティーネは自分の民族を本来の場所へ戻すという目的を持って、聖杯戦争に参加しているようである。彼女は聖杯に叶えてもらいたい特別な願いは持っていない。', tags = NULL, voice_actor = '諸星すみれ' WHERE character_id = 'CH011504'; -- ティーネ・チェルク
UPDATE characters SET description = NULL, tags = NULL, voice_actor = '寺澤百花' WHERE character_id = 'CH011506'; -- ヴィオラ・ヴァルストロム
UPDATE characters SET description = 'マスターとの出会いの際、真のアサシンはファルデウスの信念に疑問を投げかけ、それが他者の命を奪う価値があるのかと問う。それが彼との契約を結ぶことの本質だと宣言するのだ。彼はマスターの影となることに同意するが、その条件はマスターが信念を捨てないことである。ファルデウスは、もし一つの答えを誤っていたなら、アサシンに殺されていただろうと考えている。アサシンは古風な話し方をするキャラクターで、例えば「あなた」の代わりに古い敬語表現を用いる。アサシンの真の名前はハサン・サッバーハであり、「幽霊の織り手のハサン」という異名を持つ。この者は「老人」の称号を得た個人である。', tags = ARRAY['白髪','老人','クール','真面目','無口','剣士']::text[], voice_actor = '保村真' WHERE character_id = 'CH011493'; -- ハサン・サッバーハ
UPDATE characters SET description = 'サンジェルマンは過去にフランチェスカ・プレラーティの肉体の一つを殺害したことがある。彼はライオンハートのリチャードに会いたかった。リチャードがアーサー王の遺産を探していることを知ったサンジェルマンは、酒場の酔っぱらった詩人を手配してアーサー王の遺産に関する話を広めさせた。サンジェルマンは車でリチャードのもとへ向かっていた。リチャードの家臣たちはこの男に対して警戒していたが、サンジェルマンは静かに投降し、うっかり自分の企みを口走ってしまったため、騎士たちは剣を抜きかけた。彼がアレクサンドロス大王に言及すると、リチャードは部下に退くよう命じてサンジェルマンを許す。', tags = ARRAY['おじさん','クール','悪役','社会人']::text[], voice_actor = '梶裕貴' WHERE character_id = 'CH011494'; -- サンジェルマン
UPDATE characters SET description = 'フランチェスカはジャンヌ・ダルクの時代からジル・ド・レェの友人であったフランソワ・プレラーティである。ジルが経済的困窮から悪魔召喚に手を染めるようになると、歪んだ関係の中で実際の魔術師として動いたのはプレラーティであり、ジルは単なるパトロンに過ぎなかった。元々は男性であったフランチェスカは何度も死を経験し肉体を変えているが、最初の死によって英霊として記録されることになった。英霊版のフランチェスカはその最初の死以降の記憶を持たない。', tags = ARRAY['男の娘','魔法使い','記憶喪失','人外']::text[], voice_actor = '内田真礼' WHERE character_id = 'CH011495'; -- フランチェスカ・プレラーティ
UPDATE characters SET description = NULL, tags = NULL WHERE character_id = 'CH011510'; -- シャンティ・ムカルジー
UPDATE characters SET description = 'オリオンは、もし監視者のマスターが魅力的な女性だったなら、「英霊として顕現して、一肌脱いでいただろう」とコメントしている。シグマがネーム・アサシンとの戦闘に臨む最中でも、彼は気楽な態度を保っているとされている。英霊ではなく監視者のシャドウの一体として、オリオンの外見は必ずしも彼の英霊としての姿と一致していない。', tags = ARRAY['マイペース','クール']::text[], voice_actor = '神奈延年' WHERE character_id = 'CH011476'; -- オリオン
UPDATE characters SET description = 'ウェイバー・ベルベットは、魔術協会の機関である時計塔の学生で、19歳の魔術師である。三代続く由緒ある魔術師の家系に生まれながら、才能はあるものの、同級生や講師からは認められていない。聡明な青年であるウェイバーは、魔術師の力は血筋を通じた魔力ポテンシャルの増強ではなく、努力や経験、知識を積み重ねることで高められるという革新的な理論を提唱した。しかし、この考えは彼の講師である貴族のケイネス・アーキボルド・エル=メロイに一蹴され、ウェイバーの論文は何の躊躇もなく破かれてしまう。', tags = ARRAY['黒髪','大学生','魔法使い','天才','真面目']::text[], voice_actor = '浪川大輔' WHERE character_id = 'CH011505'; -- ウェイバー・ベルベット
