UPDATE characters SET description = '純血種の吸血鬼の少女。「破壊の鬼子」という異名を持ち、大陸最強の天才魔法攻撃手。訓練中、彼女が無邪気に遊び半分で繰り出す、山や大地をも削り取るほどの圧倒的な攻撃魔法によって、リックは何度も殺されている。その容姿からは信じられないほどの大食漢である。', tags = ARRAY['銀髪','ロリ','小柄','吸血鬼','魔法使い','天才']::text[], voice_actor = '久野美咲' WHERE character_id = 'CH006291'; -- アリスレート・ドラクル
UPDATE characters SET description = 'ケルヴィン・ウルヴォルフは拳王大会の三度の優勝者である。相手が強いほど興奮し、何よりも戦闘を楽しむ男だ。優れた嗅覚を用いて相手の力量と言葉の真偽を見抜く特殊な能力を持っている。', tags = ARRAY['おじさん','筋肉質','格闘家','ライバル','武道家','S属性']::text[], voice_actor = '小西克幸' WHERE character_id = 'CH006292'; -- ケルヴィン・ウルヴォルフ
UPDATE characters SET description = '非常に心優しいBランク冒険者。24歳で転職した遅咲きの冒険者として、30歳を超えてから冒険者になったリックに励まされている。仕事やイベントに積極的に参加し、周囲から好かれている。', tags = ARRAY['おじさん','社会人','元気','真面目']::text[], voice_actor = '長岡龍歩' WHERE character_id = 'CH006293'; -- リンクス・ローロット
UPDATE characters SET description = 'リーネット・エルフェルトはダークエルフで、リックのアシスタント兼相棒。かつて地下闘技場で伝説の9999連勝を成し遂げた経歴を持つ。現在はメイド姿で「オリハルコンフィスト」の家事全般を担当している。あるきっかけでリックと出会い、彼をパーティに勧誘する。', tags = ARRAY['黒髪','ロングヘア','メイド服','褐色肌','お姉さん','クール','ヒロイン','格闘家','エルフ']::text[], voice_actor = '大西沙織' WHERE character_id = 'CH006288'; -- リーネット・エルフェルト
UPDATE characters SET description = 'ディアルムート公爵の次男で、アンジェリカの弟。わずか11歳にして、C級相当の魔法操作能力を持つと言われており、E級昇進試験を受ける他の候補者たちを遠く引き離している。幼少期から天才児として育てられ、周囲から大きな期待を寄せられていたせいか、横柄で尊大な態度をとっている。', tags = ARRAY['ショタ','天才','魔法使い','お嬢様','ナルシスト']::text[], voice_actor = '徳留慎乃佑' WHERE character_id = 'CH006298'; -- フリード・ディルムット
UPDATE characters SET description = 'ブロストン・アッシュオークは、冒険者となった戦闘僧侶のオークで、怪物的な肉体と知性から「賢き獣」と呼ばれている。現在は「オリハルコン・フィスト」を率いており、リックは彼を師匠として慕っている。その巨大な体格に似合わず、回復魔法を含むサポート魔法に長けており、死後間もない者であれば蘇生させることも可能だ。', tags = ARRAY['黒髪','おじさん','筋肉質','褐色肌','獣耳(その他)','長身','武道家','魔法使い','人外','格闘家']::text[], voice_actor = '三宅健太' WHERE character_id = 'CH006289'; -- ブロストン・アッシュオーク
UPDATE characters SET description = '生まれつき傑出した戦闘能力とスキルを持つ大柄な男。一度暴走すると止められない、気分の浮き沈みが激しい危険人物で、兄のスネイプにさえ多くの厄介事をもたらしている。', tags = ARRAY['黒髪','長身','おじさん','筋肉質','S属性']::text[], voice_actor = '住永侑太' WHERE character_id = 'CH006295'; -- ギース・リザレクト
UPDATE characters SET description = '中年男性で、ギースの兄。拳王トーナメントの西部リーグ運営委員会の委員長を務めており、かつてボクサーとして活躍していた。弟のギースとは対照的に温厚な人物だが、裏社会との繋がりがあるという絶えない噂が絶えない。', tags = ARRAY['おじさん','社会人','武道家']::text[], voice_actor = '一条和矢' WHERE character_id = 'CH006294'; -- スネイプ・リザレクト
UPDATE characters SET description = 'アンジェリカ・ディルムットは、北方の貴族を統一する名門ディルムット公爵家の長女であり、王立騎士団の二級騎士である。強化魔法「瞬脚」を使った高速戦闘スキルで「閃光のアンジェリカ」として知られている。言葉はやや厳しいところがあるものの、努力家であり、兄弟姉妹に対して優しい一面を見せている。', tags = ARRAY['銀髪','ロングヘア','お姉さん','真面目','ツンデレ','騎士','魔法使い','剣士']::text[], voice_actor = '下地紫野' WHERE character_id = 'CH006296'; -- アンジェリカ・ディルムット
UPDATE characters SET description = '少女のような見た目をした、エルフとドワーフのハーフ（実年齢は50歳以上）。この世界の科学技術では製造不可能な武器の開発を続けており、1000年先の未来の技術にアクセスしているという噂から「千年工房職人」の異名を持つ。無敵のスケベ親父である。', tags = ARRAY['小柄','おじさん','エルフ','人外','ナルシスト','S属性']::text[], voice_actor = '豊永利行' WHERE character_id = 'CH006290'; -- ミゼット・エルドワーフ
UPDATE characters SET description = 'リューは勇美艾ラが卵から育てた竜である。', tags = ARRAY['人外']::text[] WHERE character_id = 'CH003996'; -- リュー
UPDATE characters SET description = 'ゲーム『光魔法と勇者』の隠しボスとして異世界転生した少女。当初は平穏な人生を送るつもりだったが、ダンジョンで初めて魔法の力を使った時に「ゲーマー魂」に火がついてしまい、あっという間にレベル上げの沼にはまっていった。ユミエラ・ドルクネスは冷静で理性的、常に無表情という特徴を持っており、他者との関係構築や感情の理解といった人間関係の構築が苦手である。そうした性格に加え、王国内で恐れられ差別の対象となっている漆黒の黒髪という見た目も相まって、周囲の人間から敬遠され、距離を置かれることが多い。', tags = ARRAY['黒髪','ロリ','クール','無口','魔法使い','異世界転生','クーデレ']::text[] WHERE character_id = 'CH003985'; -- ユミエラ・ドルクネス
UPDATE characters SET description = 'パトリック・アッシュバトンは王立アカデミーの学生であり、ユミエラの最も親しい友人だ。辺境伯の次男で、戦術と風魔法に優れている。元のゲーム『光魔法と勇者』では単なるモブキャラに過ぎなかった。パトリック・アッシュバトンは誠実で心優しく、冷静沈着な人物で、ユミエラの奇想天外な行動に対してツッコミ役を務めることが多い。彼女が別の男性に「自分より強い人しか好きじゃない」と言って断るのを聞いて以降、毎日レベルアップのために努力し始める（ユミエラがそれが単なる言い訳だということを知っていても）。', tags = ARRAY['金髪','ショタ','制服','真面目','クール']::text[] WHERE character_id = 'CH003986'; -- パトリック・アッシュバトン
