UPDATE characters SET description = 'ザガンの悪事の相棒、つまりは唯一の友人。ザガンと同等かそれ以上の力を持つ。彼もまた魔王候補の一人である。', tags = ARRAY['クール','魔王','ライバル','人外']::text[], voice_actor = '谷山紀章' WHERE character_id = 'CH005129'; -- バルバロス
UPDATE characters SET description = 'ザガンが百万金貨で買った美しいエルフ。最初は彼を警戒していたが、やがて彼のそばにいることで安心感を覚えるようになる。彼が気持ちをうまく表現できないときでも、彼のことを理解することができる。', tags = ARRAY['エルフ','ヒロイン','人外','おっとり']::text[], voice_actor = '市ノ瀬加那' WHERE character_id = 'CH005124'; -- ネフェリア
