UPDATE characters SET description = 'ザガンを襲撃して力を奪おうとした若き竜。自らの力を求める野心から、ザガンに立ちはだかった。', tags = ARRAY['角','翼','人外']::text[], voice_actor = '美坂朱音' WHERE character_id = 'CH005127'; -- ウォルフォレ
