UPDATE characters SET description = '「魔王」の候補者の一人である若き力強い魔導士。容姿端麗な18歳の青年で、一目惚れしたエルフ奴隷を買い取ることになる。', tags = ARRAY['青髪','ショタ','クール','魔法使い','魔王','ナルシスト']::text[], voice_actor = '小林裕介' WHERE character_id = 'CH005125'; -- ザガン
