UPDATE characters SET description = '好物：たこ焼き　嫌いな食べ物：椎茸　最近嬉しかったこと：ソシャゲで★5キャラを3体引いた

姉母ネモは毒舌でぶっきらぼうな少女。相手を挑発する癖があり、かなり生意気な性格をしている。幼馴染の間島アコヤとは、戦う時に息がぴったり合うチームワークを見せるが、頻繁に言い争いもしている。それでも、二人の間には恋愛感情があるかもしれない。', tags = ARRAY['黒髪','ツンデレ','小悪魔','中学生','小柄','魔法使い','幼馴染']::text[] WHERE character_id = 'CH004010'; -- 姉母ネモ
UPDATE characters SET description = '阿良河キウィはSNSで魔法少女たちに注目が集まるのが気に入らず、彼女たちを叩きのめすためにエノルメータのメンバーになった。当初はウテナに敵意を抱いていた阿良河キウィだったが、ショック療法を受けた後は従順になり、ウテナに好意を寄せるようになった。今では、ウテナから認められるだけで満足している。阿良河キウィはウテナとラブホテルに行くことを頻繁に妄想している。見た目とは違い、学業成績は十分に優秀で、ウテナの成績低下を防ぐのを手助けできるほどである。彼女とマギア・サルファーは本能的に対立関係にあり、すぐに罵り合ったり喧嘩したりするようになる。', tags = ARRAY['黒髪','小柄','ロリ','中学生','ツンデレ','ヤンデレ','S属性']::text[] WHERE character_id = 'CH004008'; -- 阿良河キウィ
UPDATE characters SET description = '柊うてなは内気で引っ込み思案な少女で、魔法少女に憧れており、彼女たちのグッズを集めたり、熱く語ったりしている。トレスマギアへの執着は彼女たちと一緒に戦いたいという願いにまで至ったが、それが原因でヴェナリータに騙されてしまう。時折、素直で単純な一面を見せることもある。', tags = ARRAY['黒髪','ロリ','中学生','天然','ドジ','魔法使い']::text[] WHERE character_id = 'CH004009'; -- 柊うてな
UPDATE characters SET description = '好物：卵焼き 嫌いな食べ物：パクチー 最近の野望：自分の歌声動画がSNSでバズること

阿古屋真珠は陽気な女の子だ。しかし同時にかなり自己中心的で、批判に非常に敏感である。彼女はエノルメ卿とマギア・ベーサー・ウテナの両者を恐れており、二人とも罰として性的嫌がらせを用いるという共通点を見いだしている。彼女は露出狂的な行為をする時以外は歌が壊滅的に下手だが、この事実はウテナがネモが傷つけられるという脅迫の下で彼女に全裸での歌唱を強要した時に判明した。', tags = ARRAY['元気','ナルシスト','中学生','魔法使い']::text[] WHERE character_id = 'CH004011'; -- 阿古屋真珠
UPDATE characters SET description = '杜乃こりすは物静かで控えめな女の子で、エノルメータの最年少メンバーです。彼女にとって大切な懐かしいおもちゃを大量に集めています。彼女のテーマは「不思議の国のアリス」です。', tags = ARRAY['ロリ','小柄','無口','小学生','魔法使い']::text[] WHERE character_id = 'CH004007'; -- 杜乃こりす
