UPDATE characters SET description = 'シスタギガントは非常に従順で、命令には異議を唱えず、罰せられても抗わない性格をしている。また、憂鬱な一面もあり、何かの出来事で泣いたり嘆いたりする姿がしばしば見られる。ただし、エノルムの命令には盲目的に従っているものの、本当の忠誠心はベナリタに向けられている。', tags = ARRAY['M属性','おっとり','シスター']::text[] WHERE character_id = 'CH004015'; -- シスタギガント
UPDATE characters SET description = '花菱はるかは非常に元気で衝動的な少女で、いつも笑顔で自分の気持ちのままに行動している。才能と力を持つ魔法少女として活躍する沙世と香織子のことを大切に思い、彼女たちを心から尊敬している。しかし同時に、非常にお人好しで騙されやすく、知恵や常識に欠けているようなところがある。そうした面がありながらも、花菱はるかは友達を心から思いやり、どんな困難があっても仲間を守るために立ち向かう優しい少女である。バイザーに操られていた時のことを振り返る時、硫黄とアズールに危害を加えてしまったことに対して強い後悔と羞恥心を感じている。', tags = ARRAY['元気','ドジ','天然','お嬢様','中学生','魔法使い']::text[] WHERE character_id = 'CH004014'; -- 花菱はるか
UPDATE characters SET description = 'ターニャ・デグレチャフは、かわいらしく愛らしい、そして美しい少女の姿をしている。しかし内面では、権力への執着が強く、道徳観に欠け、冷酷で、残忍で、短気な性格をしている。特に戦闘中は、任務を遂行するためなら敵に対して容赦ない残虐性と殺意を露わにする。また、部下の失敗と不服従を徹底的に許さない。仕事に対しては忠実で、常に迅速な完遂を求める。ターニャ・デグレチャフは、軍での急速な昇進の裏にある自分の容姿について、誰からの差別も決して許さない。', tags = ARRAY['金髪','ショートヘア','幼女','ロリ','小柄','白肌','細身','軍服','S属性','クール','真面目','ナルシスト','主人公','小学生','魔法使い','天才']::text[], voice_actor = '悠木碧' WHERE character_id = 'CH012982'; -- ターニャ・デグレチャフ
UPDATE characters SET description = 'ヴィクトーリヤ・イヴァーノヴナ・セレブリャコーフは帝国軍の魔導師であり徴兵兵で、かつてはターニャ率いる第3小隊の一員だった。その後、新設された航空大隊「V601」に配属され、ターニャの副官として仕える。', tags = ARRAY['銀髪','ロングヘア','細身','軍服','クール','魔法使い']::text[], voice_actor = '早見沙織' WHERE character_id = 'CH012984'; -- ヴィクトーリヤ・イヴァーノヴナ・セレブリャコーフ
UPDATE characters SET description = '帝国陸軍の将軍にして作戦部長。大規模な戦略立案から細部にわたる作戦の調整まで、幅広く優れた手腕を発揮する有能な軍人。参謀総長ゼットゥールの友人である。', tags = ARRAY['おじさん','真面目','軍服','天才']::text[], voice_actor = '玄田哲章' WHERE character_id = 'CH012985'; -- クルト・フォン・ルーデルドルフ
UPDATE characters SET description = '帝国陸軍の将軍にして参謀総長。 豊富な知識を備えた合理主義者。作戦部長ルーデルスドルフと協力し、戦略の立案と実行にあたる。', tags = ARRAY['白髪','メガネ','おじさん','軍服','クール','真面目','社会人']::text[], voice_actor = '大塚芳忠' WHERE character_id = 'CH012986'; -- ハンス・フォン・ゼートゥーア
UPDATE characters SET description = '帝国軍司令部の戦略本部に所属する高級将校。帝国の戦術を担当する参謀本部の戦略顧問の一員である。思慮深く聡明な人物で、ターニャ・デグレチャフの正体を素早く見抜き、彼女を悪魔と呼ぶ。それでもなお、彼は彼女の冷徹さと効率性で任務を完璧に遂行することを信頼している。', tags = ARRAY['黒髪','真面目','クール','社会人','天才']::text[], voice_actor = '三木眞一郎' WHERE character_id = 'CH012983'; -- エーリッヒ・フォン・レルゲン
UPDATE characters SET description = '友近壇ノ浦と共に異世界に迷い込んだ高校生。人生のほとんどを隠し続けてきた、対象を問答無用で即座に死に至らしめる力を持つ。', tags = ARRAY['黒髪','高校生','クール','異世界転生']::text[], voice_actor = '内山昂輝' WHERE character_id = 'CH004021'; -- 高遠夜霧
UPDATE characters SET description = '与儀の同級生で、旅の仲間。彼が守り続ける存在だが、戦闘歌のプログラムとは相性が悪い。', tags = ARRAY['黒髪','ヒロイン']::text[], voice_actor = '富田美憂' WHERE character_id = 'CH004022'; -- 壇ノ浦知千佳
UPDATE characters SET description = '与儀里のクラスをバスごと異世界に召喚した賢者。彼女自身も以前、異世界に召喚され、冒険の末に賢者となったが、莫大な魔力を持つため、常識がやや欠けている。', tags = ARRAY['金髪','お姉さん','天然','マイペース','魔法使い','異世界転生']::text[], voice_actor = '堀江由衣' WHERE character_id = 'CH004024'; -- 賢者シオン
UPDATE characters SET description = '壇ノ浦もこもこは朋花の先祖にして守護霊である。平安時代の幽霊でありながら、現代文化に造詣が深く、デジタル技術も気軽に使いこなしている。', tags = ARRAY['白髪','お姉さん','おっとり','人外']::text[], voice_actor = '金田朋子' WHERE character_id = 'CH004023'; -- 壇ノ浦もこもこ
UPDATE characters SET description = '高遠朝霞は、ヨギリ・タカトウの代理母であり保護者である。研究所からヨギリを育てるよう任命された若い日本人女性で、ヨギリに名前を付けたのは彼女である。その後、ヨギリは彼女の名前を自分の名前として使うようになった。', tags = ARRAY['社会人']::text[], voice_actor = 'Lynn' WHERE character_id = 'CH004042'; -- 高遠朝霞
UPDATE characters SET description = '彼女は異世界を統治する賢者の一人である。同時に最高位の吸血鬼であり、不死の肉体を持つ。トレードマークは鮮やかな赤いドレス。とあるきっかけで余裁に興味を持ち、彼を探している。', tags = ARRAY['赤髪','ロングヘア','ドレス','お姉さん','クール','吸血鬼']::text[], voice_actor = '佐藤利奈' WHERE character_id = 'CH004038'; -- 賢者レイン
