UPDATE characters SET description = 'タイプ：メイド 職業：専属メイド 初登場：第30章 彼女ナンバー008 花園波々里の専属メイド。銘戸芽衣は礼儀正しく上品で、強い感情をめったに見せない。波々里に絶対的な忠誠を誓っており、波々里から許可や指示を受けない限り、ほぼ何もしようとしない。蓮太郎ファミリーと花園ファミリーへの狂信的な忠誠心により、蓮太郎や波々里、他の彼女たちを脅かしたり、侮辱したり、少しでも不便をかけたりする人物の「排除」を喜んで申し出る。銘戸芽衣は万能型のメイドである。ほぼあらゆることができるようにみえ、', tags = ARRAY['黒髪','ロングヘア','お嬢様','クール','メイド服','大学生','執事']::text[], voice_actor = '三森すずこ' WHERE character_id = 'CH008139'; -- 銘戸芽衣
UPDATE characters SET description = 'タイプ：ハングリー系 職業：中学3年生 登場：24章 彼女ナンバー007 

原賀胡桃は食べることが大好きで、新陳代謝が非常に高い。そのため、ほぼ常にお腹が空いており、その時に欲しい特定の食べ物を食べていないと、すぐに不機嫌になってしまう。原賀胡桃は食べ物に関して強い連想癖を持っている。ほぼあらゆることが食べ物を連想させ、そうなると欲しい食べ物を食べないと機嫌が悪くなってしまう。', tags = ARRAY['黒髪','中学生','元気','ドジ']::text[], voice_actor = '進藤あまね' WHERE character_id = 'CH008143'; -- 原賀胡桃
UPDATE characters SET description = 'タイプ：ドM 職業：高校1年生、野球部員 初登場：第33章 彼女ナンバー009 須藤育は野球を心から愛しており、部が廃部の危機に瀕した時には何時間もかけて部員の勧誘活動に奔走するほど。どんな状況でも全力を尽くそうとする姿勢から、レンタローには「禁欲主義の化身」と評されている。須藤育はかなりのドMで、身体が悲鳴を上げるまで何時間も練習し、その苦痛を楽しむほどである。', tags = ARRAY['黒髪','高校生','M属性','真面目','ボーイッシュ']::text[], voice_actor = '高橋李依' WHERE character_id = 'CH008133'; -- 須藤育
UPDATE characters SET description = 'タイプ：クーデレ 職業：高校1年生 初登場：第6章 彼女No.004 凪乃は実用性を何より重視し、どんな状況でも最も効率的な方法で問題を解決することに執着している。凪乃はヒロインの中で最も頭が良い。学校の試験では満点（700/700）を取得しており、これは他の漫画の天才キャラクターのスコアを上回る。凪乃は円周率を数百桁まで暗記しており、時々それを自分を落ち着かせるために使用している。彼女の極めて高い知性と効率性のおかげで、ほとんどの困難な状況で凪乃は最初に解決策を思いつく。しかし', tags = ARRAY['クーデレ','高校生','天才','ヒロイン']::text[], voice_actor = '瀬戸麻沙美' WHERE character_id = 'CH008140'; -- 栄逢凪乃
