UPDATE characters SET description = '彼は召喚事件に巻き込まれた日本の学生の一人で、クラスメイトたちと共にトルタスに迷い込んでしまった。クラスの大半の生徒から慕われており、事実上クラス全体のリーダー的存在である。さらに、稀有な職業である「勇者」という適性を与えられたことで、その立場はより強固なものになっている。', tags = ARRAY['黒髪','高校生','主人公','勇者','真面目','天才']::text[], voice_actor = '柿原徹也' WHERE character_id = 'CH007122'; -- 天之河光輝
UPDATE characters SET description = 'ティオ・クラルスはMが主体質の「変態」だが、正直者であり、彼女の放つ言葉は古い伝説のようである。彼女のM的性格は、ウル村北部の山でハジメ達に敗北したことが契機となって形成された。彼女は忠誠心が厚く、ハジメに身を捧げて奴隷となることを誓い、それ以降彼のことを「ご主人様」と呼んでいる。', tags = ARRAY['M属性','ヒロイン']::text[], voice_actor = '日笠陽子' WHERE character_id = 'CH007110'; -- ティオ・クラルス
