UPDATE characters SET description = 'カム・ハウリアはハウリア族の族長で、当初は温厚な性格だった。しかし、ハジメに鍛えられた後は残忍な性格へと変わり、族内随一の暗殺者となった。熊人族50人の集団さえも撃破するほどの実力を持つようになる。', tags = ARRAY['クール','人外']::text[], voice_actor = '金光宣明' WHERE character_id = 'CH007119'; -- カム・ハウリア
UPDATE characters SET description = '園部優花は、召喚事件に巻き込まれた日本の学生の一人で、クラスメイトたちと共にトータスへ転移してきた。田中貴江と宮崎菜々の友人であり、愛子の護衛として王国の策略を含むあらゆる危険から彼女を守る任務に当たっていた。', tags = ARRAY['黒髪','高校生','転校生']::text[], voice_actor = '富田美憂' WHERE character_id = 'CH007118'; -- 園部優花
UPDATE characters SET description = '香織の親友。光希の幼馴染で、実家は道場を営んでいる。雫は真面目で優しく思いやりのある女の子で、日々剣術の修行に励んでいる。クールで凛とした美女として見られているが、実はピンク色が好きなど、かわいいものやネコやウサギといったかわいい動物が好きなおませな一面を持っている。本当の気持ちを隠し、他の人に心配をかけないようにと、強気な顔を見せることが多い。', tags = ARRAY['黒髪','ロングヘア','高校生','真面目','クール','ツンデレ','幼馴染','武道家','剣士']::text[], voice_actor = '花守ゆみり' WHERE character_id = 'CH007111'; -- 八重樫 雫
UPDATE characters SET description = '召喚事件に巻き込まれた日本の学生の一人で、クラスメイトたちと共にトルタスへと異世界転移した。天之河光希、八重樫雫、白崎香織の幼馴染であり、大迷宮オルクスでの修行中は光希のパーティーに所属していた。また、谷口鈴の彼氏でもある。', tags = ARRAY['黒髪','高校生','幼馴染','異世界転生']::text[], voice_actor = '木島隆一' WHERE character_id = 'CH007114'; -- 坂上龍太郎
