UPDATE characters SET description = '斎藤の従妹であり、同じクラスの生徒。人形のような可愛らしい容姿とクールな表情が特徴で、兄妹のように一緒に育った斎藤の良き友人である。', tags = ARRAY['黒髪','クール','高校生','クーデレ']::text[], voice_actor = '稗田寧々' WHERE character_id = 'CH008153'; -- 北条糸青
UPDATE characters SET description = '東京の桃太郎支部の職員であり、月読のパートナー。血に飢えた男で、戦闘の興奮を求めてばかりおり、泥野などの鬼に挑んで強い相手との戦いに望みを託している。彼の桃太郎パワーは、24時間以内に目撃した能力なら自分の細菌を使ってコピーすることができる。最終的に怒りに敗北するが、他の桃太郎職員に回収されて生き残る。', tags = ARRAY['社会人','S属性','クール']::text[], voice_actor = '小野友樹' WHERE character_id = 'CH009955'; -- 桃角c
UPDATE characters SET description = '志希のクラスメイトであり、彼の想い人。過去に両親から激しい虐待を受けた経験から、常に謝罪的で自分を卑下する傾向がある。彼女の血蝕解放は「血の巨人」として顕現し、かつて両親から彼女を守ってくれていた姉の姿をした巨大な鬼のような存在となる。その姉は父親に殺されている。', tags = ARRAY['黒髪','ロングヘア','高校生','ヒロイン','真面目','M属性','人外']::text[], voice_actor = '石見舞菜香' WHERE character_id = 'CH009964'; -- 屏風ヶ浦帆稀
UPDATE characters SET description = 'ラセツ学園の謎めいた校長。無田野とは良好な関係にあるものの、直接会話することはほとんどなく、ほぼ常に伝統的な和装で全身を覆っている。その素顔は青い肌を持つ両性具有的な男性で、全身に刺青が入っている。', tags = ARRAY['白髪','青髪','長身','おじさん','教師','人外','妖怪']::text[], voice_actor = '緒方恵美' WHERE character_id = 'CH009965'; -- 校長
UPDATE characters SET description = '式のクラスメイトで、かつて暮らしていた鬼の村で踊り手をしていた。病気で鬼の彼女を失ったことから、あらゆる不快な状況を極度に嫌う性格になっている。血月解放は紙製の扇と踊り装束として顕現し、彼の村での踊り手としての過去を反映している。', tags = ARRAY['クール','人外','妖怪']::text[], voice_actor = '三浦魁' WHERE character_id = 'CH009966'; -- 手術岾ロクロ
UPDATE characters SET description = '式のクラスの生徒。一見すると落ち着きがあり知性的に見えるが、実は筋金入りの変態で、童貞を卒業しようと頻繁に試みるも失敗ばかり。血蝕解放は超音波として発現し、隙間に染み込んで比較的遠い距離まで伝播することで発動する。', tags = ARRAY['高校生','制服','ナルシスト','S属性']::text[], voice_actor = '花江夏樹' WHERE character_id = 'CH009958'; -- 遊摺部従児
UPDATE characters SET description = '桃寺神門は桃太郎であり、桃太郎企業の13部隊の元副隊長で、隊長の桃岩真也の下で指揮を執っていた。', tags = ARRAY['ショタ','社会人','ボーイッシュ']::text[], voice_actor = '土岐隼一' WHERE character_id = 'CH009953'; -- 桃寺神門
UPDATE characters SET description = '識の同級生。普段は無愛想で気の強い印象だが、弱々しく見える者や心惹かれた相手に対しては、母性本能が刺激されて思わず世話を焼いてしまう癖がある。漣水鶏はこれに付け込んで桐山を無理やり付き合わせており、本人は大迷惑。血月解放の能力は킥복싱グローブの姿で発現する。', tags = ARRAY['黒髪','ツンデレ','格闘家']::text[], voice_actor = '愛美' WHERE character_id = 'CH009967'; -- 漣水鶏
UPDATE characters SET description = '京都の桃太郎支部の隊長。サディスティックな性格で、暴走した鬼の子どもが師匠とその家族を殺害した事件をきっかけに共感能力を失い、その後は主に鬼の死骸を解剖する科学者として働いてきた。桃太郎の能力により、自らが移植した菌を介して操る死体やホムンクルスなどの造物を操ることができる。鬼の京都支部への襲撃を指揮した後、目覚めた式の円気の力を受けて致命傷を負い、最終的には無田野に止めを刺される。', tags = ARRAY['クール','S属性','悪役','社会人','無口']::text[], voice_actor = '岸尾だいすけ' WHERE character_id = 'CH009956'; -- 桃宮唾切
UPDATE characters SET description = '東京桃太郎支部の幹部で、大介のパートナー。桃太郎の力により、引いたタロットカードに基づいて細菌から兵士を生成できる能力を持つ。その力の影響で占いに極度に依存しており、不吉な運勢を引いた場合は戦闘を避けることが多い。無田野に敗れるが、命は助けられる。', tags = ARRAY['社会人','魔法使い']::text[], voice_actor = '浅沼晋太郎' WHERE character_id = 'CH009957'; -- 桃華月詠
UPDATE characters SET description = '式の担任教師。無口で厳格な男性で、高い格闘能力を持ち、鬼からも桃太郎からも一目置かれている。移動の際はローラースケートを使うことが多い。その血蝕解放は傘の姿をしている。', tags = ARRAY['黒髪','ショートヘア','長身','おじさん','クール','真面目','無口','教師','格闘家']::text[], voice_actor = '神谷浩史' WHERE character_id = 'CH009950'; -- 無陀野無人
