UPDATE characters SET description = 'エルハルトはメルロマルク城下町の鍛冶屋にして武器屋の店主である。彼の店はメルロマルクで唯一、盾を取り扱っている。他の店が宗教的理由から盾を売らないのに対し、エルハルトの店だけが盾を販売している。', tags = ARRAY['おじさん','社会人']::text[], voice_actor = '安元洋貴' WHERE character_id = 'CH009988'; -- エルハルト
