UPDATE characters SET description = '異世界に弓の勇者として召喚された高校生。普段は冷静で礼儀正しいが、救世主意識が強く、正義感に燃えている。自分の行動の結果を考えずに悪人を倒そうとする傾向がある。ただし、これは彼が未熟だからに過ぎず、悪意があるわけではない。', tags = ARRAY['高校生','クール','真面目','勇者','異世界転生']::text[], voice_actor = '山谷祥生' WHERE character_id = 'CH009980'; -- 川澄樹
